'use strict';
(async()=>{const say=(text,error)=>{const m=document.querySelector('#legal-message');if(!m)return;m.textContent=text;if(error)m.dataset.tone='error';else delete m.dataset.tone};
const $=s=>document.querySelector(s),esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function request(path,options={}){let r;try{r=await fetch(path,{credentials:'same-origin',headers:{'Content-Type':'application/json'},...options,signal:AbortSignal.timeout(15000)})}catch(e){throw Error(e?.name==='TimeoutError'?'The request took too long. Please try again.':navigator.onLine===false?'You appear to be offline. Check your connection and try again.':'Could not reach RepoShelf. Check your connection and try again.')}const data=await r.json().catch(()=>null);if(!r.ok||!data)throw Error(data?.error?.message||(r.status>=500?'RepoShelf is having trouble right now. Please try again in a moment.':'Please try again.'));return data}
const saveConsent=value=>{localStorage.setItem('reposhelf.analytics.consent.v1',value?'yes':'no');if(!value){localStorage.removeItem('reposhelf.analytics.visitor');sessionStorage.removeItem('reposhelf.analytics.session')}window.dispatchEvent(new Event('reposhelf-privacy'))};
try{const config=await request('/api/auth?action=legal');$('#legal-operator').innerHTML=config.active?`<p class="legal-meta">Operator: ${esc(config.operator)} · ${esc(config.country)} · <a href="mailto:${esc(config.contactEmail)}">${esc(config.contactEmail)}</a></p>`:`<p class="legal-meta">Service: ${esc(config.serviceName||'RepoShelf')}${config.country?' · '+esc(config.country):''}</p><p class="legal-notice">Draft: the legal operator identity and dedicated contact email must be confirmed before activation. Account agreement acceptance is not yet activated.</p>`;document.querySelectorAll('.legal-contact').forEach(el=>{el.innerHTML=config.active?`<a href="mailto:${esc(config.contactEmail)}">${esc(config.contactEmail)}</a>`:'contact details will be published before activation'});
if(!$('#legal-session'))return;const session=await request('/api/auth');if(!session.user){$('#legal-session').innerHTML='<p>Sign in with GitHub to review your account agreement.</p><a class="button lime" href="/api/auth?action=start">Sign in with GitHub ↗</a>';return}
$('#legal-session').innerHTML=`<p>Signed in as <strong>${esc(session.user.name)}</strong>.</p>`;if(!config.active){say('Legal setup is awaiting confirmation of the operator identity and dedicated contact email. You can continue browsing.');return}if(session.legal?.ready===false){say('A database update is needed before acceptance can be recorded. Ask the administrator to apply migration 5.',true);return}if(!session.legal?.required){$('#legal-session').innerHTML+='<p>You have accepted the current Terms of Service and acknowledged the Privacy Policy.</p><a class="button lime" href="/">Continue to RepoShelf</a>';return}
$('#legal-accept-form').hidden=false;$('#agree-legal').onchange=()=>$('#accept-button').disabled=!$('#agree-legal').checked;
$('#legal-accept-form').onsubmit=async e=>{e.preventDefault();if(!$('#agree-legal').checked)return;$('#accept-button').disabled=true;try{await request('/api/auth?action=accept-legal',{method:'POST',body:JSON.stringify({terms:config.version,privacy:config.version,agree:true})});try{saveConsent(true)}catch{say('Agreement saved. Your browser could not store the analytics setting, so analytics stays off.')}location.href='/'}catch(error){say(error.message,true);$('#accept-button').disabled=false}}
}catch(error){$('#legal-operator').textContent='Operator details are temporarily unavailable.';if($('#legal-message'))say(error.message,true)}
})();
